// Checkout conversion module - tracks paid events and triggers revenue autopilot
const fs = require('fs');
const path = require('path');

const CONVERSION_LOG = '/var/log/checkout_conversions.log';

function logConversion(event) {
  const entry = {
    ts: new Date().toISOString(),
    event: event,
    paid: true
  };
  fs.appendFileSync(CONVERSION_LOG, JSON.stringify(entry) + '\n');
  return entry;
}

function getPaidEventCount() {
  try {
    const data = fs.readFileSync(CONVERSION_LOG, 'utf8');
    const lines = data.trim().split('\n').filter(l => l);
    return lines.length;
  } catch (e) {
    return 0;
  }
}

module.exports = { logConversion, getPaidEventCount };
